<script lang="ts">
 import {fullReportPrice} from './lib/pricing';
 import Story from './Story.svelte';
 import Explorer from './Explorer.svelte';
 import ReportTools from './ReportTools.svelte';
 import {exampleInputs,emptyInputs,calculateInputs,type ScenarioInputs} from './lib/scenario-inputs';
 import RequestForm from './RequestForm.svelte';
 import ToolIllustration from './ToolIllustration.svelte';
 import {stages,type RequestBrief} from './lib/request';
 import {onMount} from 'svelte';
 import {modalFocus} from './lib/modal';
 import {MapPin,Search,Download,CalendarDays,FileText,LayoutDashboard,ChevronRight,Check,Menu,X,SlidersHorizontal,Store,TrainFront,Car,Utensils,ShieldCheck,LogOut,Globe,Compass,ArrowUpRight,RefreshCw} from 'lucide-svelte';
 import Map from './lib/Map.svelte';import {counts,money,scenario,category,type Area,type RequestRecord} from './lib/model';import {supabase} from './lib/backend';import {downloadReport} from './lib/report';
 function storedLanguage():'en'|'ms'{try{return localStorage.getItem('loka-v2-language')==='ms'?'ms':'en';}catch{return 'en';}}
 let lang=$state<'en'|'ms'>(storedLanguage());const t=(en:string,ms:string)=>lang==='en'?en:ms;
 let page=$state('home');let mobile=$state(false);let areas=$state<Area[]>([]);let selected=$state('ss15');let query=$state('');let filter=$state('all');let loading=$state(true);let loadError=$state('');let toast=$state('');let authOpen=$state(false);let email=$state('');let authBusy=$state(false);let user=$state<any>(null);let demo=$state(true);let records=$state<RequestRecord[]>([]);let orders=$state<any[]>([]);let activeStep=$state(0);let checkoutBusy=$state(false);let confirmReset=$state(false);
 let inputs=$state<ScenarioInputs>(exampleInputs());
 let scenarioMode=$state<'example'|'own'>('example');
 let scenarioDrafts:Record<'example'|'own',ScenarioInputs>={example:exampleInputs(),own:emptyInputs()};
 function changeScenarioMode(next:'example'|'own'){if(next===scenarioMode)return;scenarioDrafts[scenarioMode]={...inputs};inputs={...scenarioDrafts[next]};scenarioMode=next;}
 let pendingArea='';let formArea=$state('');let lastSaved=$state<RequestRecord|null>(null);
 const area=$derived(areas.find(a=>a.id===selected)||areas[0]);
 const calc=$derived(calculateInputs(inputs));
 const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur'}).format(new Date());
 const samples=():RequestRecord[]=>[{id:'DEMO-1042',kind:'consultation',company:'Kopi & Co. Studio',area:'SS15',business:'cafe',date:'',message:'A fictional company exploring its first café.',status:'requested',created_at:new Date().toISOString()},{id:'DEMO-1041',kind:'report',company:'Kopi & Co. Studio',area:'TTDI',business:'cafe',date:'',message:'Sample custom report request for a second location.',status:'in_review',created_at:new Date().toISOString()}];
 function notify(s:string){toast=s;setTimeout(()=>toast='',6500);}
 function navigate(p:string){location.hash=p;mobile=false;}
 function saveLocal(next:RequestRecord[]){localStorage.setItem('loka-v2-demo-requests',JSON.stringify(next));}
 async function loadRecords(){if(demo){try{const saved=JSON.parse(localStorage.getItem('loka-v2-demo-requests')||'null');records=Array.isArray(saved)?saved.filter(r=>r&&typeof r.id==='string'&&typeof r.company==='string'&&typeof r.message==='string'&&['report','consultation'].includes(r.kind)):samples();}catch{records=samples();}orders=[];return;}if(user&&supabase){const [r,o]=await Promise.all([supabase.from('requests').select('*').order('created_at',{ascending:false}),supabase.from('orders').select('*').order('created_at',{ascending:false})]);if(r.error||o.error){notify(t('Could not load your records. Please try again.','Rekod tidak dapat dimuatkan. Sila cuba lagi.'));records=[];orders=[];}else{records=r.data||[];orders=o.data||[];}}else{records=[];orders=[];}}
 function beginDemo(){demo=true;authOpen=false;loadRecords();navigate('dashboard');}
 function resetDemo(){try{localStorage.removeItem('loka-v2-demo-requests');}catch{notify(t('Browser storage is unavailable. The demo could not be reset.','Storan pelayar tidak tersedia. Demo tidak dapat ditetapkan semula.'));return;}pendingArea='';formArea='';lastSaved=null;selected='ss15';query='';filter='all';records=samples();inputs=exampleInputs();scenarioMode='example';scenarioDrafts={example:exampleInputs(),own:emptyInputs()};activeStep=0;confirmReset=false;notify(t('Demo reset for the next visitor.','Demo ditetapkan semula untuk pelawat seterusnya.'));}
 async function login(provider=false){if(!supabase){notify(t('Account sign-in will be available after Supabase is connected. You can use the booth demo now.','Log masuk akan tersedia selepas Supabase disambungkan. Anda boleh gunakan demo sekarang.'));return;}authBusy=true;try{const result=provider?await supabase.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin}}):await supabase.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin}});if(result.error)throw result.error;if(!provider)notify(t('Check your email for a sign-in link.','Semak e-mel anda untuk pautan log masuk.'));}catch(e:any){notify(e.message);}finally{authBusy=false;}}
 async function logout(){await supabase?.auth.signOut();user=null;demo=true;loadRecords();}
 async function submitRequest(brief:RequestBrief):Promise<boolean>{
  const profile=stages.find(s=>s[0]===brief.stage);
  const record:RequestRecord={id:crypto.randomUUID(),kind:page==='consultation'?'consultation':'report',company:brief.company,area:brief.area,business:brief.business,date:page==='consultation'?brief.date:'',message:[brief.message,brief.budget!==undefined?'Budget / Bajet: '+money(brief.budget):'',profile?'Stage / Peringkat: '+profile[1]+' / '+profile[2]:'',page==='consultation'?(brief.goal==='report'?'Focus / Fokus: Understand my report / Fahami laporan saya':'Focus / Fokus: Find or compare locations / Cari atau bandingkan lokasi'):''].filter(Boolean).join('\n'),status:'requested',created_at:new Date().toISOString()};
  try{const next=[record,...records];saveLocal(next);records=next;lastSaved=record;formArea='';navigate('dashboard');return true;}
  catch{notify(t('This request was not saved because browser storage is unavailable. Your form details are still here; please try again.','Permintaan tidak disimpan kerana storan pelayar tidak tersedia. Butiran borang masih ada; sila cuba lagi.'));return false;}
 }
 function startRequest(kind:'custom'|'consultation'){pendingArea=area?.name||'';navigate(kind);}
 async function checkout(requestId:string){if(demo||!user){authOpen=true;notify(t('Stripe test checkout requires a connected account. Sample reports are free to download in the booth demo.','Pembayaran ujian Stripe memerlukan akaun disambungkan. Laporan contoh boleh dimuat turun percuma dalam demo.'));return;}checkoutBusy=true;try{const {data,error}=await supabase!.functions.invoke('checkout',{body:{request_id:requestId}});if(error)throw error;if(!data?.url?.startsWith('https://checkout.stripe.com/'))throw new Error(t('Checkout is not configured yet.','Pembayaran belum dikonfigurasi.'));location.assign(data.url);}catch(e:any){notify(t('Test checkout unavailable. ','Pembayaran ujian tidak tersedia. ')+e.message);}finally{checkoutBusy=false;}}
 function download(){if(area&&calc){downloadReport(area,lang,{customers:inputs.customers!,basket:inputs.basket!,days:inputs.days!,margin:inputs.margin!,fixed:inputs.fixed!});notify(t('Sample PDF prepared with sources and assumptions. Check your browser’s downloads.','PDF contoh disediakan bersama sumber dan andaian. Semak muat turun pelayar anda.'));}}
 onMount(()=>{const desktop=window.matchMedia('(min-width: 1101px)');const closeOnDesktop=()=>{if(desktop.matches)mobile=false;};desktop.addEventListener('change',closeOnDesktop);const routes=['home','services','explore','reports','consultation','custom','dashboard','method'];const route=()=>{const p=location.hash.slice(1);if(p==='main')return;const next=routes.includes(p)?p:'home';if(next!==page){if(next==='custom'||next==='consultation'){formArea=pendingArea;pendingArea='';}page=next;mobile=false;window.scrollTo({top:0,behavior:'instant'});}};route();window.addEventListener('hashchange',route);fetch('/data/locations.json').then(r=>{if(!r.ok)throw new Error('Data unavailable');return r.json();}).then(data=>{areas=data;if(!data.length)throw new Error('No saved data');}).catch(()=>loadError=t('Location data could not load. Please reload the page.','Data lokasi tidak dapat dimuatkan. Sila muat semula halaman.')).finally(()=>loading=false);loadRecords();supabase?.auth.getSession().then(({data})=>{user=data.session?.user||null;if(user){demo=false;loadRecords();}});const subscription=supabase?.auth.onAuthStateChange((_event,session)=>{user=session?.user||null;if(user){demo=false;queueMicrotask(loadRecords);}else if(!demo){records=[];orders=[];}});return()=>{desktop.removeEventListener('change',closeOnDesktop);window.removeEventListener('hashchange',route);subscription?.data.subscription.unsubscribe();};});
