<header><a class="brand" href="#home" aria-label="LOKA WISE home"><img src="/logo.png" alt="LOKA WISE"/><span>LOKA <b>WISE</b><small>INSIGHTS FOR A STRONGER TOMORROW</small></span></a><nav class="desktop-nav" aria-label={t('Main navigation','Navigasi utama')}>
