 <div id="mobile-drawer" class="mobile-drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1" use:modalFocus={()=>mobile=false}>
  <div class="drawer-heading"><span id="drawer-title">LOKA <b>WISE</b><small>INSIGHTS FOR A STRONGER TOMORROW</small></span><button class="icon-button" aria-label={t('Close navigation','Tutup navigasi')} onclick={()=>mobile=false}><X size={23}/></button></div>
  <span class="micro drawer-label">{t('EXPLORE LOKA WISE','TEROKAI LOKA WISE')}</span>
  <nav class="drawer-nav" aria-label={t('Mobile navigation','Navigasi mudah alih')}>
   {#each [['home',t('Our story','Cerita kami')],['services',t('Services','Perkhidmatan')],['explore',t('Location insights','Wawasan lokasi')],['reports',t('Sample analysis','Analisis contoh')],['dashboard',t('My workspace','Ruang saya')]] as [key,label],i}
    <a href={'#'+key} aria-current={page===key?'page':undefined} onclick={(e)=>{e.preventDefault();navigate(key);}}><span><small>0{i+1}</small>{label}</span><ArrowUpRight size={19}/></a>
   {/each}
  </nav>
  <div class="drawer-bottom"><a class="story-button navy" href="#consultation" onclick={(e)=>{e.preventDefault();navigate('consultation');}}>{t('Let’s discuss your location','Bincangkan lokasi anda')}<ArrowUpRight size={18}/></a><a class="drawer-account" href="#custom" onclick={(e)=>{e.preventDefault();navigate('custom');}}>{t('Request a custom report','Minta laporan tersuai')}<ArrowUpRight size={16}/></a><p>MY / MALAYSIA</p></div>
 </div>
</div>
{/if}


<main id="main" tabindex="-1">
